import{A as e,E as t,d as n,l as r,p as i}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as a}from"./app-DRV_K-uf.js";var o=JSON.parse(`{"path":"/%E5%90%8E%E7%AB%AF%E5%BC%80%E5%8F%91/%E6%95%B0%E6%8D%AE%E5%BA%93/PostgreSQL/04_%E5%AE%9E%E6%88%98%E7%AF%87/02_PostgreSQL%E8%BF%81%E7%A7%BB%E5%AE%9E%E6%88%98.html","title":"PostgreSQL 迁移实战","lang":"zh-CN","frontmatter":{"title":"PostgreSQL 迁移实战","order":2,"category":["数据库","PostgreSQL"],"tag":["PostgreSQL","实战","迁移","MySQL","pgLoader"]},"git":{"createdTime":1780573763000,"updatedTime":1780573763000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":8.64,"words":2593},"filePathRelative":"后端开发/数据库/PostgreSQL/04_实战篇/02_PostgreSQL迁移实战.md"}`),s={name:`02_PostgreSQL迁移实战.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),r(`div`,null,[o[0]||=n(`<h1 id="postgresql-迁移实战" tabindex="-1"><a class="header-anchor" href="#postgresql-迁移实战"><span>PostgreSQL 迁移实战</span></a></h1><p>从 MySQL / Oracle 迁移到 PostgreSQL 是许多团队面临的技术决策。PG 更强的标准 SQL 兼容性、丰富的类型体系、开源生态（<a href="https://github.com/supabase/supabase" target="_blank" rel="noopener noreferrer">Supabase</a>、<a href="https://github.com/PostgREST/postgrest" target="_blank" rel="noopener noreferrer">PostgREST</a>）让它成为关系型数据库迁移的热门目标。但迁移不只是数据搬运，还涉及数据类型映射、SQL 方言适配、应用代码改造。</p><h2 id="一、迁移全流程" tabindex="-1"><a class="header-anchor" href="#一、迁移全流程"><span>一、迁移全流程</span></a></h2>`,3),i(d,{code:`eJxLy8kvT85ILCpR8AniUgACx2hDPYUX61ue7NnwZEffi+UtTzsmxSro6topOEUb6SkEJ2ek5iYqvNjf+Hz57liwDiewrHO0sZ7Cs6kbnvWuQ5Z0Bku6RJvoKTzdNeX5lBVPdi9+vqDxZUPTy9ZeiBIXsBLXaFOY/mcLFr5c1QORdAVLukWb6Sk8b9zwdNeypx3tz3oXQSTdwJLu0eZAydkTn/UtB7r46ex5z3bPiuUCKyguqcxJVXBUSMvMybFSTjVMM01LRZJwh0lYpJmmWnIBAFEAaXw=`}),o[1]||=n(`<table><thead><tr><th>阶段</th><th>关键任务</th><th>风险点</th></tr></thead><tbody><tr><td>评估与规划</td><td>数据量估算、兼容性分析、停机窗口</td><td>低估复杂度</td></tr><tr><td>Schema 迁移</td><td>DDL 转换、数据类型映射、索引重建</td><td>类型映射错误</td></tr><tr><td>数据迁移</td><td>全量导出导入、增量同步</td><td>数据丢失/乱码</td></tr><tr><td>应用代码适配</td><td>SQL 方言改写、ORM 配置、驱动替换</td><td>边界 case</td></tr><tr><td>数据校验</td><td>行数、checksum、业务抽检</td><td>校验不充分</td></tr><tr><td>灰度切换</td><td>读写分离、双写、流量切换</td><td>切换故障</td></tr><tr><td>监控与回滚</td><td>性能监控、回滚预案</td><td>回滚不可用</td></tr></tbody></table><h2 id="二、mysql-→-postgresql-数据类型映射" tabindex="-1"><a class="header-anchor" href="#二、mysql-→-postgresql-数据类型映射"><span>二、MySQL → PostgreSQL 数据类型映射</span></a></h2><p>MySQL 和 PostgreSQL 的类型体系差异较大，以下是核心映射表：</p><table><thead><tr><th>MySQL 类型</th><th>PostgreSQL 类型</th><th>注意事项</th></tr></thead><tbody><tr><td><code>INT</code></td><td><code>INTEGER</code></td><td>兼容，无需转换</td></tr><tr><td><code>TINYINT</code></td><td><code>SMALLINT</code></td><td>PG 无 TINYINT，用 SMALLINT 替代</td></tr><tr><td><code>SMALLINT</code></td><td><code>SMALLINT</code></td><td>完全兼容</td></tr><tr><td><code>BIGINT</code></td><td><code>BIGINT</code></td><td>完全兼容</td></tr><tr><td><code>FLOAT</code></td><td><code>REAL</code></td><td>精度可能微差，金融场景用 <code>NUMERIC</code></td></tr><tr><td><code>DOUBLE</code></td><td><code>DOUBLE PRECISION</code></td><td>兼容</td></tr><tr><td><code>DECIMAL(M,N)</code></td><td><code>NUMERIC(M,N)</code></td><td>完全兼容</td></tr><tr><td><code>VARCHAR(N)</code></td><td><code>VARCHAR(N)</code></td><td>兼容</td></tr><tr><td><code>CHAR(N)</code></td><td><code>CHAR(N)</code></td><td>兼容</td></tr><tr><td><code>TEXT</code></td><td><code>TEXT</code></td><td>兼容</td></tr><tr><td><code>DATETIME</code></td><td><code>TIMESTAMP</code></td><td>PG TIMESTAMP 更精确（微秒级）</td></tr><tr><td><code>DATE</code></td><td><code>DATE</code></td><td>兼容</td></tr><tr><td><code>TIME</code></td><td><code>TIME</code></td><td>兼容</td></tr><tr><td><code>YEAR</code></td><td><code>SMALLINT</code></td><td>PG 无 YEAR 类型</td></tr><tr><td><code>ENUM</code></td><td><code>ENUM</code> 或 <code>TEXT</code> + CHECK</td><td>PG 的 ENUM 需先 CREATE TYPE</td></tr><tr><td><code>SET</code></td><td><code>TEXT[]</code> 或 <code>JSONB</code></td><td>PG 无 SET，用数组替代</td></tr><tr><td><code>JSON</code></td><td><code>JSONB</code></td><td><strong>强烈建议用 JSONB</strong>，支持索引和查询</td></tr><tr><td><code>BLOB</code></td><td><code>BYTEA</code></td><td>二进制存储，接口不同</td></tr><tr><td><code>AUTO_INCREMENT</code></td><td><code>SERIAL</code> / <code>BIGSERIAL</code> / <code>IDENTITY</code></td><td>推荐用 IDENTITY（PG 10+）</td></tr><tr><td><code>UNSIGNED</code></td><td>无直接对应</td><td>用 CHECK 约束或更大类型</td></tr><tr><td><code>BOOLEAN</code>（TINYINT(1)）</td><td><code>BOOLEAN</code></td><td>PG 原生布尔类型</td></tr></tbody></table><div class="hint-container important"><p class="hint-container-title">关键差异</p><ol><li><strong>AUTO_INCREMENT → IDENTITY</strong>：<code>SERIAL</code> 是旧语法（PG 10 之前），新项目建议用 <code>GENERATED ALWAYS AS IDENTITY</code>，更符合 SQL 标准</li><li><strong>UNSIGNED 不存在</strong>：PG 没有无符号整数，需要用 <code>CHECK (col &gt;= 0)</code> 约束或升级到大一号的类型</li><li><strong>JSON → JSONB</strong>：PG 的 <code>JSON</code> 只是文本存储，<code>JSONB</code> 才支持索引和高性能查询，务必用 JSONB</li><li><strong>ENUM 语义不同</strong>：MySQL 的 ENUM 是列级定义，PG 需要 <code>CREATE TYPE</code> 先定义枚举类型</li></ol></div><h3 id="_2-1-auto-increment-迁移示例" tabindex="-1"><a class="header-anchor" href="#_2-1-auto-increment-迁移示例"><span>2.1 AUTO_INCREMENT 迁移示例</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> users</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;"> AUTO_INCREMENT </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- PostgreSQL（方式一：SERIAL，兼容旧习惯）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> users</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id </span><span style="color:#C678DD;">SERIAL</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- PostgreSQL（方式二：IDENTITY，推荐，PG 10+）</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> users</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id </span><span style="color:#C678DD;">INTEGER</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    name</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-2-enum-迁移示例" tabindex="-1"><a class="header-anchor" href="#_2-2-enum-迁移示例"><span>2.2 ENUM 迁移示例</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> orders</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;"> AUTO_INCREMENT </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    status</span><span style="color:#ABB2BF;"> ENUM(</span><span style="color:#98C379;">&#39;pending&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;paid&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;shipped&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;cancelled&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- PostgreSQL</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TYPE</span><span style="color:#61AFEF;"> order_status</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> ENUM (</span><span style="color:#98C379;">&#39;pending&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;paid&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;shipped&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;cancelled&#39;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> orders</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id </span><span style="color:#C678DD;">INTEGER</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#C678DD;">    status</span><span style="color:#ABB2BF;"> order_status </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#98C379;"> &#39;pending&#39;</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 后续新增枚举值</span></span>
<span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> TYPE</span><span style="color:#ABB2BF;"> order_status </span><span style="color:#C678DD;">ADD</span><span style="color:#C678DD;"> VALUE</span><span style="color:#98C379;"> &#39;refunded&#39;</span><span style="color:#C678DD;"> AFTER</span><span style="color:#98C379;"> &#39;shipped&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-3-unsigned-迁移示例" tabindex="-1"><a class="header-anchor" href="#_2-3-unsigned-迁移示例"><span>2.3 UNSIGNED 迁移示例</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> products</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;"> UNSIGNED AUTO_INCREMENT </span><span style="color:#C678DD;">PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    price </span><span style="color:#C678DD;">DECIMAL</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) UNSIGNED </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    stock </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;"> UNSIGNED </span><span style="color:#C678DD;">DEFAULT</span><span style="color:#D19A66;"> 0</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- PostgreSQL：用 CHECK 约束替代 UNSIGNED</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> products</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#ABB2BF;">    id </span><span style="color:#C678DD;">INTEGER</span><span style="color:#C678DD;"> GENERATED</span><span style="color:#C678DD;"> ALWAYS</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> IDENTITY</span><span style="color:#C678DD;"> PRIMARY KEY</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#ABB2BF;">    price </span><span style="color:#C678DD;">NUMERIC</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#C678DD;"> CHECK</span><span style="color:#ABB2BF;"> (price </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">    stock </span><span style="color:#C678DD;">INTEGER</span><span style="color:#C678DD;"> DEFAULT</span><span style="color:#D19A66;"> 0</span><span style="color:#C678DD;"> CHECK</span><span style="color:#ABB2BF;"> (stock </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="三、迁移工具" tabindex="-1"><a class="header-anchor" href="#三、迁移工具"><span>三、迁移工具</span></a></h2><h3 id="_3-1-pgloader-——-通用迁移利器" tabindex="-1"><a class="header-anchor" href="#_3-1-pgloader-——-通用迁移利器"><span>3.1 pgLoader —— 通用迁移利器</span></a></h3><p><a href="https://github.com/dimitri/pgloader" target="_blank" rel="noopener noreferrer">pgLoader</a> 是最推荐的 PostgreSQL 迁移工具，支持 MySQL、SQLite、CSV、dBase 等多种数据源。</p><div class="language-ini line-numbers-mode" data-highlighter="shiki" data-ext="ini" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-ini"><span class="line"><span style="color:#98C379;">-- pgloader 配置文件：mysql_to_pg.load</span></span>
<span class="line"><span style="color:#98C379;">LOAD DATABASE</span></span>
<span class="line"><span style="color:#98C379;">    FROM mysql://root:password@192.168.1.10/mydb</span></span>
<span class="line"><span style="color:#98C379;">    INTO postgresql://postgres:password@192.168.1.20/mydb</span></span>
<span class="line"></span>
<span class="line"><span style="color:#98C379;">WITH</span></span>
<span class="line"><span style="color:#98C379;">    include drop,        -- 导入前先 DROP 目标表</span></span>
<span class="line"><span style="color:#98C379;">    create tables,       -- 自动创建表</span></span>
<span class="line"><span style="color:#98C379;">    create indexes,      -- 自动创建索引</span></span>
<span class="line"><span style="color:#98C379;">    reset sequences,     -- 重置序列值</span></span>
<span class="line"><span style="color:#98C379;">    downcase identifiers -- 标识符转小写</span></span>
<span class="line"></span>
<span class="line"><span style="color:#98C379;">SET</span></span>
<span class="line"><span style="color:#98C379;">    maintenance_work_mem to </span><span style="color:#98C379;">&#39;512MB&#39;</span><span style="color:#98C379;">,</span></span>
<span class="line"><span style="color:#98C379;">    work_mem to </span><span style="color:#98C379;">&#39;128MB&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#98C379;">CAST</span></span>
<span class="line"><span style="color:#98C379;">    type datetime to timestamptz using zero-dates-to-null,</span></span>
<span class="line"><span style="color:#98C379;">    type tinyint to smallint,</span></span>
<span class="line"><span style="color:#98C379;">    type mediumint to integer,</span></span>
<span class="line"><span style="color:#98C379;">    type double to double precision,</span></span>
<span class="line"><span style="color:#98C379;">    type enum to text,</span></span>
<span class="line"><span style="color:#98C379;">    type year to smallint</span></span>
<span class="line"></span>
<span class="line"><span style="color:#98C379;">BEFORE LOAD DO</span></span>
<span class="line"><span style="color:#98C379;">    $$ CREATE SCHEMA IF NOT EXISTS mydb</span><span style="color:#7F848E;font-style:italic;">; $$</span></span>
<span class="line"></span>
<span class="line"><span style="color:#98C379;">AFTER LOAD DO</span></span>
<span class="line"><span style="color:#98C379;">    $$ ALTER TABLE mydb.users ALTER COLUMN created_at SET DEFAULT now()</span><span style="color:#7F848E;font-style:italic;">; $$</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 执行迁移</span></span>
<span class="line"><span style="color:#61AFEF;">pgloader</span><span style="color:#98C379;"> mysql_to_pg.load</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出示例：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2026-06-04T10:00:00.000000+08 INFO Starting pgloader</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2026-06-04T10:00:05.000000+08 INFO Cloning MySQL schema...</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2026-06-04T10:00:30.000000+08 INFO Copying data...</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#                    Table name       reads   written     time</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#              mydb.users           50000     50000   2.345s</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#             mydb.orders          200000    200000   8.123s</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">#           mydb.products            5000      5000   0.456s</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2026-06-04T10:01:00.000000+08 INFO Finishing...</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2026-06-04T10:01:01.000000+08 INFO Done in 61.000s</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">pgLoader CAST 规则</p><p>pgLoader 的 <code>CAST</code> 是迁移的核心配置，必须根据业务仔细调整：</p><ul><li><code>datetime to timestamptz using zero-dates-to-null</code>：MySQL 的 <code>0000-00-00</code> 日期转为 NULL</li><li><code>enum to text</code>：先迁移为 TEXT，后续手动创建 ENUM 类型</li><li><code>tinyint to smallint</code>：PG 无 TINYINT</li></ul></div><h3 id="_3-2-aws-schema-conversion-tool-sct" tabindex="-1"><a class="header-anchor" href="#_3-2-aws-schema-conversion-tool-sct"><span>3.2 AWS Schema Conversion Tool（SCT）</span></a></h3><p>适用于大型企业迁移，特别是 Oracle → PostgreSQL 场景：</p><ul><li>自动分析源库 Schema 并生成转换报告</li><li>评估迁移复杂度和兼容性</li><li>自动转换存储过程、触发器、视图</li><li>支持 Oracle、MySQL、SQL Server → PostgreSQL</li></ul><h3 id="_3-3-ora2pg-——-oracle-迁移专用" tabindex="-1"><a class="header-anchor" href="#_3-3-ora2pg-——-oracle-迁移专用"><span>3.3 ora2pg —— Oracle 迁移专用</span></a></h3><p><a href="https://ora2pg.darold.net/" target="_blank" rel="noopener noreferrer">ora2pg</a> 是最成熟的 Oracle → PostgreSQL 迁移工具：</p><ul><li>支持 Schema、数据、存储过程、触发器、视图的完整迁移</li><li>可导出为 SQL 文件或直接导入 PG</li><li>PL/SQL → PL/pgSQL 的自动转换（不完美，需人工审查）</li></ul><h3 id="_3-4-工具选择指南" tabindex="-1"><a class="header-anchor" href="#_3-4-工具选择指南"><span>3.4 工具选择指南</span></a></h3><table><thead><tr><th>场景</th><th>推荐工具</th></tr></thead><tbody><tr><td>MySQL → PG</td><td>pgLoader</td></tr><tr><td>Oracle → PG</td><td>ora2pg + AWS SCT</td></tr><tr><td>SQLite → PG</td><td>pgLoader</td></tr><tr><td>CSV → PG</td><td><code>COPY</code> 命令或 pgLoader</td></tr><tr><td>自定义复杂迁移</td><td>自写脚本 + <code>COPY</code></td></tr></tbody></table><h2 id="四、常见陷阱" tabindex="-1"><a class="header-anchor" href="#四、常见陷阱"><span>四、常见陷阱</span></a></h2><h3 id="_4-1-标识符大小写" tabindex="-1"><a class="header-anchor" href="#_4-1-标识符大小写"><span>4.1 标识符大小写</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL：标识符不区分大小写</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> Users</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">Name</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">));</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> users;  </span><span style="color:#7F848E;font-style:italic;">-- OK</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- PostgreSQL：未引用的标识符自动转为小写</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> Users</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">Name</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">));</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 实际创建的表名是 &quot;users&quot;，列名是 &quot;name&quot;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> users;  </span><span style="color:#7F848E;font-style:italic;">-- OK</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 但如果创建时用了双引号，大小写被保留</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> &quot;</span><span style="color:#61AFEF;">Users</span><span style="color:#ABB2BF;">&quot; (</span><span style="color:#98C379;">&quot;Name&quot;</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">));</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> users;  </span><span style="color:#7F848E;font-style:italic;">-- ERROR: relation &quot;users&quot; does not exist</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#98C379;"> &quot;Name&quot;</span><span style="color:#C678DD;"> FROM</span><span style="color:#98C379;"> &quot;Users&quot;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- OK，但以后每次都要加引号</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">最佳实践</p><ul><li><strong>永远不要</strong>用双引号创建标识符</li><li>迁移前将 MySQL 中的标识符统一转小写</li><li>pgLoader 的 <code>downcase identifiers</code> 选项可自动处理</li></ul></div><h3 id="_4-2-保留字冲突" tabindex="-1"><a class="header-anchor" href="#_4-2-保留字冲突"><span>4.2 保留字冲突</span></a></h3><p>MySQL 和 PG 的保留字不同，迁移后可能出现语法冲突：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL 中 &quot;user&quot; 不是保留字</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> user</span><span style="color:#ABB2BF;"> (id </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">name</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">));  </span><span style="color:#7F848E;font-style:italic;">-- MySQL OK</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- PostgreSQL 中 &quot;user&quot; 是保留字</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> user</span><span style="color:#ABB2BF;"> (id </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">name</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">));  </span><span style="color:#7F848E;font-style:italic;">-- PG ERROR!</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 必须加引号或改名</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> &quot;</span><span style="color:#61AFEF;">user</span><span style="color:#ABB2BF;">&quot; (id </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">name</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">));  </span><span style="color:#7F848E;font-style:italic;">-- 不推荐</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> TABLE</span><span style="color:#61AFEF;"> app_user</span><span style="color:#ABB2BF;"> (id </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">name</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">));  </span><span style="color:#7F848E;font-style:italic;">-- 推荐</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常见 PG 保留字（MySQL 可用但 PG 不行）：<code>user</code>、<code>order</code>、<code>group</code>、<code>table</code>、<code>index</code>、<code>type</code>、<code>check</code>、<code>default</code>、<code>primary</code>。</p><h3 id="_4-3-limit-without-order-by" tabindex="-1"><a class="header-anchor" href="#_4-3-limit-without-order-by"><span>4.3 LIMIT without ORDER BY</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL：无 ORDER BY 的 LIMIT 结果&quot;相对稳定&quot;（InnoDB 按主键顺序）</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- PostgreSQL：无 ORDER BY 的 LIMIT 结果**不确定**</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 每次执行可能返回不同的行！</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;">-- 可能每次结果不同</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 必须加 ORDER BY</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> id </span><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-4-存储过程重写" tabindex="-1"><a class="header-anchor" href="#_4-4-存储过程重写"><span>4.4 存储过程重写</span></a></h3><p>MySQL 的存储过程语法与 PG 的 PL/pgSQL 差异较大：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL 存储过程</span></span>
<span class="line"><span style="color:#ABB2BF;">DELIMITER //</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> PROCEDURE</span><span style="color:#ABB2BF;"> get_user_orders(</span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> p_user_id </span><span style="color:#C678DD;">INT</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> p_user_id;</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#56B6C2;"> COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> total </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> p_user_id;</span></span>
<span class="line"><span style="color:#C678DD;">END</span><span style="color:#ABB2BF;"> //</span></span>
<span class="line"><span style="color:#ABB2BF;">DELIMITER ;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- PostgreSQL PL/pgSQL</span></span>
<span class="line"><span style="color:#C678DD;">CREATE OR REPLACE</span><span style="color:#C678DD;"> FUNCTION</span><span style="color:#61AFEF;"> get_user_orders</span><span style="color:#ABB2BF;">(p_user_id </span><span style="color:#C678DD;">INTEGER</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">RETURNS</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;">(order_id </span><span style="color:#C678DD;">BIGINT</span><span style="color:#ABB2BF;">, title </span><span style="color:#C678DD;">TEXT</span><span style="color:#ABB2BF;">, amount </span><span style="color:#C678DD;">NUMERIC</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> $$</span></span>
<span class="line"><span style="color:#C678DD;">BEGIN</span></span>
<span class="line"><span style="color:#C678DD;">    RETURN</span><span style="color:#ABB2BF;"> QUERY</span></span>
<span class="line"><span style="color:#C678DD;">        SELECT</span><span style="color:#ABB2BF;"> id, title, amount </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> user_id </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> p_user_id;</span></span>
<span class="line"><span style="color:#C678DD;">END</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">$$ </span><span style="color:#C678DD;">LANGUAGE</span><span style="color:#ABB2BF;"> plpgsql;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键差异：</p><ul><li>PG 用 <code>FUNCTION</code> 而非 <code>PROCEDURE</code>（PG 11+ 支持 PROCEDURE 但语义不同）</li><li>PG 函数必须有 <code>RETURNS</code> 声明</li><li>PG 用 <code>$$</code> 而非 <code>DELIMITER</code></li><li>PG 的流程控制语法不同（<code>IF ... THEN ... END IF</code>、<code>LOOP ... END LOOP</code>）</li></ul><h2 id="五、数据迁移执行" tabindex="-1"><a class="header-anchor" href="#五、数据迁移执行"><span>五、数据迁移执行</span></a></h2><h3 id="_5-1-全量迁移" tabindex="-1"><a class="header-anchor" href="#_5-1-全量迁移"><span>5.1 全量迁移</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 方法一：pgLoader（推荐，自动化程度高）</span></span>
<span class="line"><span style="color:#61AFEF;">pgloader</span><span style="color:#98C379;"> mysql_to_pg.load</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 方法二：手动导出导入（适合小数据量）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1. MySQL 导出 CSV</span></span>
<span class="line"><span style="color:#61AFEF;">mysql</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> &quot;SELECT * FROM orders&quot;</span><span style="color:#D19A66;"> -B</span><span style="color:#98C379;"> mydb</span><span style="color:#ABB2BF;"> | </span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#61AFEF;">    sed</span><span style="color:#98C379;"> &#39;s/\\t/,/g; s/^/&quot;/; s/$/&quot;/; s/,/&quot;,&quot;/g&#39;</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">orders.csv</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. PostgreSQL 导入</span></span>
<span class="line"><span style="color:#61AFEF;">\\copy</span><span style="color:#98C379;"> orders</span><span style="color:#98C379;"> FROM</span><span style="color:#98C379;"> &#39;/tmp/orders.csv&#39;</span><span style="color:#98C379;"> WITH</span><span style="color:#ABB2BF;"> (FORMAT </span><span style="color:#98C379;">csv,</span><span style="color:#98C379;"> HEADER</span><span style="color:#D19A66;"> true</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-增量同步-零停机迁移" tabindex="-1"><a class="header-anchor" href="#_5-2-增量同步-零停机迁移"><span>5.2 增量同步（零停机迁移）</span></a></h3><p>大型系统需要零停机迁移，核心是<strong>全量 + 增量</strong>两阶段：</p>`,45),i(d,{code:``}),o[2]||=n(`<p>增量同步工具：</p><ul><li><strong>Debezium</strong> + <strong>Kafka</strong>：捕获 MySQL Binlog，写入 PG</li><li><strong>pg_chameleon</strong>：MySQL 到 PG 的复制工具</li><li>自建脚本：解析 Binlog → 生成 PG SQL</li></ul><h2 id="六、数据校验" tabindex="-1"><a class="header-anchor" href="#六、数据校验"><span>六、数据校验</span></a></h2><p>迁移后必须验证数据完整性，不能只看行数。</p><h3 id="_6-1-校验脚本" tabindex="-1"><a class="header-anchor" href="#_6-1-校验脚本"><span>6.1 校验脚本</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 1. 行数对比</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- MySQL:</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#98C379;"> &#39;users&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> tbl, </span><span style="color:#56B6C2;">COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> cnt </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users</span></span>
<span class="line"><span style="color:#C678DD;">UNION ALL</span><span style="color:#C678DD;"> SELECT</span><span style="color:#98C379;"> &#39;orders&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders</span></span>
<span class="line"><span style="color:#C678DD;">UNION ALL</span><span style="color:#C678DD;"> SELECT</span><span style="color:#98C379;"> &#39;products&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> products;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- PostgreSQL:</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#98C379;"> &#39;users&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> tbl, </span><span style="color:#56B6C2;">COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> cnt </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> users</span></span>
<span class="line"><span style="color:#C678DD;">UNION ALL</span><span style="color:#C678DD;"> SELECT</span><span style="color:#98C379;"> &#39;orders&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders</span></span>
<span class="line"><span style="color:#C678DD;">UNION ALL</span><span style="color:#C678DD;"> SELECT</span><span style="color:#98C379;"> &#39;products&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> products;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 2. 关键表 Checksum</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- PostgreSQL:</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> md5(</span><span style="color:#56B6C2;">string_agg</span><span style="color:#ABB2BF;">(t::</span><span style="color:#C678DD;">text</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;,&#39;</span><span style="color:#C678DD;"> ORDER BY</span><span style="color:#ABB2BF;"> id))</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> id, </span><span style="color:#C678DD;">name</span><span style="color:#ABB2BF;">, email, created_at</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> users</span></span>
<span class="line"><span style="color:#C678DD;">    ORDER BY</span><span style="color:#ABB2BF;"> id</span></span>
<span class="line"><span style="color:#ABB2BF;">) t;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 3. 数值范围校验</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#98C379;"> &#39;orders&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> tbl,</span></span>
<span class="line"><span style="color:#56B6C2;">       COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> total,</span></span>
<span class="line"><span style="color:#56B6C2;">       MIN</span><span style="color:#ABB2BF;">(amount) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> min_amount,</span></span>
<span class="line"><span style="color:#56B6C2;">       MAX</span><span style="color:#ABB2BF;">(amount) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> max_amount,</span></span>
<span class="line"><span style="color:#56B6C2;">       AVG</span><span style="color:#ABB2BF;">(amount) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> avg_amount,</span></span>
<span class="line"><span style="color:#56B6C2;">       SUM</span><span style="color:#ABB2BF;">(amount) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> sum_amount</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- 4. NULL 值分布</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> column_name, null_ratio</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#98C379;"> &#39;name&#39;</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> column_name,</span></span>
<span class="line"><span style="color:#56B6C2;">           round</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">COUNT</span><span style="color:#ABB2BF;">(*) </span><span style="color:#C678DD;">FILTER</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> name</span><span style="color:#C678DD;"> IS</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">)::</span><span style="color:#C678DD;">numeric</span><span style="color:#ABB2BF;"> / </span><span style="color:#56B6C2;">COUNT</span><span style="color:#ABB2BF;">(*) * </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">AS</span><span style="color:#ABB2BF;"> null_ratio</span></span>
<span class="line"><span style="color:#C678DD;">    FROM</span><span style="color:#ABB2BF;"> users</span></span>
<span class="line"><span style="color:#ABB2BF;">) sub;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-2-业务抽检" tabindex="-1"><a class="header-anchor" href="#_6-2-业务抽检"><span>6.2 业务抽检</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#7F848E;font-style:italic;">-- 随机抽取 100 条订单，对比 MySQL 和 PG 的数据</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> id </span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> (</span></span>
<span class="line"><span style="color:#C678DD;">    SELECT</span><span style="color:#ABB2BF;"> id </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> orders </span><span style="color:#C678DD;">ORDER BY</span><span style="color:#ABB2BF;"> random() </span><span style="color:#C678DD;">LIMIT</span><span style="color:#D19A66;"> 100</span></span>
<span class="line"><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">校验清单</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> 所有表行数一致</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> 关键表 checksum 一致</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> 数值范围（MIN/MAX/SUM）一致</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> NULL 值分布一致</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> 外键关系完整</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> 索引和约束已创建</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> 业务抽检通过</label></li></ul></div><h2 id="开源参考" tabindex="-1"><a class="header-anchor" href="#开源参考"><span>开源参考</span></a></h2><table><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://github.com/supabase/supabase" target="_blank" rel="noopener noreferrer">Supabase</a></td><td>迁移到 PG 后可直接用 Supabase 快速搭建 API 层</td></tr><tr><td><a href="https://github.com/PostgREST/postgrest" target="_blank" rel="noopener noreferrer">PostgREST</a></td><td>迁移后用 PostgREST 自动暴露 REST API</td></tr></tbody></table><h2 id="面试技巧" tabindex="-1"><a class="header-anchor" href="#面试技巧"><span>面试技巧</span></a></h2><div class="hint-container tip"><p class="hint-container-title">面试高频问题</p><ol><li><p><strong>MySQL 和 PG 的核心类型差异？</strong> 重点回答三个：<code>TINYINT → SMALLINT</code>、<code>AUTO_INCREMENT → IDENTITY</code>、<code>JSON → JSONB</code>。能说清&quot;为什么用 JSONB 而不是 JSON&quot;（索引 + 查询性能）是加分项。</p></li><li><p><strong>迁移中最容易踩的坑？</strong> 标识符大小写（PG 自动转小写）和 LIMIT without ORDER BY（PG 结果不确定）。这是&quot;做过迁移&quot;和&quot;只看过文档&quot;的分水岭。</p></li><li><p><strong>如何做到零停机迁移？</strong> 全量导出 + 增量同步（Debezium/Kafka + Binlog 解析）+ 追平延迟后切换流量。关键是&quot;增量同步&quot;这个环节。</p></li><li><p><strong>pgLoader 的 CAST 规则怎么配？</strong> 重点说 <code>datetime to timestamptz using zero-dates-to-null</code>（MySQL 的零日期问题）和 <code>enum to text</code>（先迁后改）。这两点是实操经验的体现。</p></li><li><p><strong>迁移后如何验证？</strong> 不能只看行数，还要 checksum、数值范围、NULL 分布、外键关系、业务抽检。能说出&quot;多层校验&quot;说明有生产经验。</p></li></ol></div>`,13)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};